def shortest_path(graph, source, target):
    """
    Implement a function that finds a shortest path in a weighted graph.
    It does so by implementing the shortest path in a graph with the 'Algorithm of Choice' (which is typically Dijkstra's algorithm).

    Args:
    graph (dict): A dict mapping each node to a list of (neighbour, weight) pairs.
    source: The starting node.
    target: The destination node.

    Returns:
    tuple: A tuple containing the shortest distance and the path as a list of nodes.
    If the target is unreachable, return (float("inf"), None).
    """
    import heapq

    def dijkstra(graph, start, end):
        distances = {node: float('inf') for node in graph}
        distances[start] = 0
        queue = [(0, start)]
        while queue:
            current_distance, current_node = heapq.heappop(queue)
            if current_node == end:
                return current_distance
            for neighbor, weight in graph.get(current_node, []):
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(queue, (distance, neighbor))
        return float('inf')

    shortest_dist = dijkstra(graph, source, target)
    if shortest_dist == float('inf'):
        return float('inf'), None
    else:
        from collections import deque
        def reconstruct_path(graph, start, end):
            path = deque()
            current_node = end
            while current_node != start:
                path.appendleft(current_node)
                current_node = graph[current_node][0][0]
            path.appendleft(start)
            return list(path)

        return shortest_dist, reconstruct_path(graph, source, target)

